<script>
 import {formatDate} from '$lib/date.js';
 import {onMount} from 'svelte';import {locale} from '$lib/i18n.js';import {goto} from '$app/navigation';import {listDevices,listSites,listProjects,listDeployments,listLogs} from '$lib/api.js';import {devices,notify,user} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';import Modal from '$lib/components/Modal.svelte';
 let loading=true,showAddModal=false,deviceLimit=1,allSites=[],allProjects=[],recentDeployments=[],activity=[];
 $: ru=$locale!=='en';
 onMount(async()=>{const [d,s,p,dep,logs]=await Promise.all([listDevices(),listSites(),listProjects(),listDeployments(),listLogs(8)]);if(d.ok){devices.set(d.data.devices||[]);deviceLimit=d.data.limit||1}else notify(d.error||'Не удалось загрузить устройства','error');if(s.ok)allSites=s.data.sites||[];if(p.ok)allProjects=p.data.projects||[];if(dep.ok)recentDeployments=(dep.data.deployments||[]).slice(0,5);if(logs.ok)activity=(logs.data.logs||[]).slice(0,6);loading=false});
 $: onlineCount=$devices.filter(x=>x.status==='online').length;$: runningSites=allSites.filter(x=>x.site?.status==='running').length;$: offlineCount=$devices.length-onlineCount;
 function openDevice(device){goto('/devices/'+device.id)}
</script>
<svelte:head><title>Overview · Yevqo</title></svelte:head>
<div class="welcome-row"><div><div class="eyebrow"><span class="eyebrow-line"></span> {ru?'01 / РАБОЧАЯ ОБЛАСТЬ':'01 / WORKSPACE'}</div><h1 class="page-title">{ru?'Единый интерфейс. Вся твоя инфраструктура.':'One interface. Your entire infrastructure.'}</h1><p class="page-desc">{ru?'Управляй проектами, устройствами и развёртываниями из одного места.':'Manage projects, devices and deployments from one place.'}</p></div><Button variant="primary" on:click={()=>{$devices.length>=deviceLimit?goto('/devices'):showAddModal=true}}>{$devices.length>=deviceLimit?(ru?'Лимит устройств достигнут':'Device limit reached'):(ru?'＋ Добавить устройство':'＋ Add device')}</Button></div>
{#if loading}<div class="empty">{ru?'Загружаем инфраструктуру…':'Loading infrastructure…'}</div>{:else}
<div class="overview-grid">
