 <div class="metric-card"><div class="metric-top"><span>{ru?'Подключённые устройства':'Connected devices'}</span><span class="metric-icon">▣</span></div><div class="metric-value">{onlineCount}<small> / {devices.length}</small></div><div class="metric-foot">{offlineCount} офлайн · {deviceLimit} в тарифе</div></div>
 <div class="metric-card"><div class="metric-top"><span>{ru?'Активные развёртывания':'Active deployments'}</span><span class="metric-icon">↗</span></div><div class="metric-value">—</div><div class="metric-foot">{ru?'Backend пока не предоставляет активные jobs':'Active deployment jobs are not exposed by the backend yet'}</div></div>
 <div class="metric-card"><div class="metric-top"><span>{ru?'Состояние инфраструктуры':'Infrastructure health'}</span><span class="metric-icon green">●</span></div><div class="metric-value">{devices.length===0?'—':onlineCount===devices.length?'Online':onlineCount>0?'Partial':'Offline'}</div><div class="metric-foot">{runningSites} {ru?'работающих приложений':'running applications'}</div></div>
