<div class="section-header"><div><h2 class="section-title">{ru?'Последние сайты':'Recent sites'}</h2><p class="section-subtitle">{ru?'Приложения на подключённых устройствах':'Applications on connected devices'}</p></div><a href="/sites" class="view-link">{ru?'Все сайты':'All sites'} <span>→</span></a></div>
{#if allSites.length===0}<div class="empty compact-empty">{ru?'Здесь появятся сайты, размещённые на твоих устройствах.':'Sites hosted on your devices will appear here.'}</div>{:else}<div class="sites-table-wrap"><table class="sites-table"><thead><tr><th>{ru?'САЙТ':'SITE'}</th><th>{ru?'УСТРОЙСТВО':'DEVICE'}</th><th>RUNTIME</th><th>{ru?'ПОРТ':'PORT'}</th><th>{ru?'СТАТУС':'STATUS'}</th></tr></thead><tbody>{#each allSites.slice(0,6) as item (item.device_id+'-'+item.site.site_id)}<tr on:click={()=>openDevice({id:item.device_id})}><td><strong>{item.site.site_id}</strong></td><td>{item.device_name||'Android host'}</td><td>{item.site.runtime}</td><td class="mono">:{item.site.port}</td><td><StatusDot status={item.site.status}/></td></tr>{/each}</tbody></table></div>{/if}
<div class="overview-bottom-grid">
